import itertools

def is_costas(perm):
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dc = j - i
            dr = perm[j] - perm[i]
            vec = (dr, dc)
            if vec in vectors:
                return False
            vectors.add(vec)
    return True

